(function () {
    'use strict';
    const esc = value => GameUtils.escapeHtml(String(value == null ? '' : value));
    let overlay, profiles = [], selected = null, gamePath = '', maps = [], timer, polling = false, busy = false, clients = [], clientSelection = null, clientRefresh = false, clientUpdated = 0;
    const preview = ['127.0.0.1','localhost'].includes(location.hostname) || location.protocol === 'file:';
    const modes = {dm:'Chacun pour soi / 1v1',war:'Match à mort par équipe',dom:'Domination',sd:'Recherche et destruction',conf:'Élimination confirmée',hp:'Point stratégique',koth:'Quartier général',sab:'Sabotage',ctf:'Capture du drapeau',gun:'Jeu d’armes'};
    function field(name, label, type='text', value='', extra='') {
        return `<label class="hmwh-field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
    }
    async function api(action, data={}) {
        if (preview) {
            if(action==='list')return {ok:true,profiles,gamePath:'D:\\Jeux\\HorizonMW',maps:['mp_rust','mp_shipment','mp_terminal','mp_highrise','mp_crash']};
            if(action==='save'){profiles=profiles.filter(p=>p.id!==data.id);profiles.push({...data.profile,id:data.id});return{ok:true};}
            if(action==='status')return{ok:true,running:false,ready:false,log:'Aperçu navigateur. Les journaux réels apparaissent dans WARLINK.exe.'};
            throw Error('Aperçu navigateur : le démarrage et la console sont disponibles dans WARLINK.exe.');
        }
        const result = await window.executeCommand('hmw-host',{action,...data});
        if(!result || !result.ok)throw Error(result?.error || 'Le gestionnaire serveur ne répond pas.');
        return result;
    }
    function message(text, error=false){if(!overlay)return;const el=overlay.querySelector('.hmwh-message');el.textContent=text;el.classList.toggle('error',error);}
    const hostIcons={server:'<rect x="3" y="3" width="18" height="7" rx="1"/><rect x="3" y="14" width="18" height="7" rx="1"/><path d="M6 6h2m-2 11h2"/>',players:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 5v2"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',message:'<path d="M3 3h18v13H9l-6 5Z"/>',xp:'<path d="m13 2-9 12h7l-1 8 10-13h-8Z"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>'};
    function decorateHost(){if(!overlay)return;for(const h of overlay.querySelectorAll('h3')){if(h.querySelector('.hmwh-heading-icon'))continue;const label=h.textContent.replace(/^[▣▦◈⚑]\s*/,''),key=/XP|Expérience/i.test(label)?'xp':/joueur|équipe|bot/i.test(label)?'players':/carte|rotation/i.test(label)?'map':/modération|exclusion/i.test(label)?'shield':/message/i.test(label)?'message':/configuration|règle/i.test(label)?'settings':'server';h.textContent=label;h.insertAdjacentHTML('afterbegin','<svg class="hmwh-heading-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">'+hostIcons[key]+'</svg>');}}
    function current(){return profiles.find(p=>p.id===selected);}
    function allocation(players, bots, humans, changed) {
        const integer = (v, min, max, fallback) => Math.max(min, Math.min(max, Number.isFinite(Number(v)) ? Math.round(Number(v)) : fallback));
        players=integer(players,2,18,12); bots=integer(bots,0,17,0);
        if(changed==='humans'){humans=integer(humans,1,18,1);bots=Math.min(bots,18-humans);players=Math.max(2,humans+bots);}
        else if(changed==='bots')players=Math.max(players,bots+1);
        else bots=Math.min(bots,players-1);
        return {players,bots,humans:players-bots};
    }
    function syncAllocation(changed) {
        const f=overlay?.querySelector('.hmwh-form'); if(!f)return;
        const n=allocation(f.elements.players.value,f.elements.bots.value,f.elements.humans.value,changed);
        for(const key of ['players','bots','humans'])f.elements[key].value=n[key];
        f.elements.difficulty.disabled=n.bots===0;f.elements.botWeapons.disabled=n.bots===0;
        overlay.querySelector('.hmwh-allocation').textContent=n.bots ? n.players+' places : '+n.humans+' pour les humains et '+n.bots+' bots maximum.' : n.players+' places humaines · aucun bot.';
    }
    function values() {
        syncAllocation();
        const f=overlay.querySelector('form'),data=new FormData(f),p={};
        for(const [k,v] of data)p[k]=v;
        for(const k of ['port','players','bots','scoreLimit','timeLimit','health','friendlyFire','announcementInterval','healthRegen','respawnDelay','lives','roundLimit','winLimit','xpMultiplier'])p[k]=Number(p[k]);
        for(const k of ['killstreaks','voting','headshots','hardcore','constantUav','disableSprint','thirdPerson','collision','botBalance','allowTeamChange'])p[k]=f.elements[k].checked;
        if(!p.difficulty)p.difficulty=f.elements.difficulty.value;if(!p.botWeapons)p.botWeapons=f.elements.botWeapons.value;
        p.mixModes=Array.from(f.querySelectorAll('[data-mix-mode]:checked'),x=>x.value);if(p.mode==='mix'&&!p.mixModes.length)throw Error('Coche au moins un mode.');p.rotation=p.rotation.split(/\s+/).filter(Boolean);p.id=selected;return p;
    }
    function renderList(){
        overlay.querySelector('.hmwh-profiles').innerHTML=profiles.map(p=>`<button type="button" data-profile="${esc(p.id)}" class="${p.id===selected?'active':''}"><strong>${window.WarlinkName.html(p.name)}</strong><small>UDP ${p.port} · ${esc(p.access==='public'?'Communauté WARLINK':p.access==='local'?'Local':'Privé')}</small></button>`).join('')||'<p class="hmwh-muted">Crée ton premier serveur pour commencer.</p>';
    }
    function renderForm(profile){
        const p={name:'STARZISMIK · HorizonMW',gamePath,port:27017,access:'private',password:'',serverKey:'',rconPassword:'',players:12,bots:0,difficulty:'regular',mode:'war',rotation:['mp_rust','mp_terminal'],scoreLimit:75,timeLimit:10,health:100,friendlyFire:0,killstreaks:true,voting:true,headshots:false,motd:'Bienvenue sur WARLINK',botWeapons:'mixed',botBalance:true,allowTeamChange:true,xpMultiplier:1,messagePosition:'left',respawnMessage:'',respawnPosition:profile.messagePosition||'left',healthRegen:5,respawnDelay:0,lives:0,roundLimit:1,winLimit:1,collision:true,advanced:'',...profile};
        if(!p.gamePath)p.gamePath=gamePath;
        overlay.querySelector('.hmwh-editor').innerHTML=`
            <form class="hmwh-form">
                <div class="hmwh-section-head"><h3>▣ Configuration du serveur WARLINK</h3><select name="preset" aria-label="Préréglage"><option value="">Appliquer un préréglage…</option value="duel">1v1 privé</option><option value="training">Entraînement avec bots</option><option value="public">Communauté WARLINK</option></select></div>
                <div class="hmwh-grid">
                    <div><input name="name" type="hidden" value="${esc(p.name)}"><div class="hmwh-name-editor"></div></div>
                    <div class="hmwh-access-author"><label class="hmwh-field"><span>Accès</span><select name="access"><option value="local">Local · ce PC uniquement</option><option value="private">Privé · amis / réseau</option><option value="public">Communauté WARLINK · accessible sur Internet</option></select></label>
                    <div class="hmwh-author-field">${field('author','Auteur du serveur','text',p.author||'','maxlength="48" placeholder="Ton pseudo ou ta structure"')}<small class="hmwh-muted">Nom affiché dans la liste publique. Vide : pseudo Discord.</small><label class="hmwh-author-color"><span>Couleur du logo WARLINK</span><button type="button" data-author-palette>Palette personnalisée…</button><input type="hidden" name="authorColor" value="${/^#[a-f0-9]{6}$/i.test(p.authorColor||'')?p.authorColor:'#95eb35'}" aria-label="Couleur du logo auteur"></label><div class="hmwh-author-swatches">${['#95eb35','#ffffff','#969da3','#36a2ff','#32d8e6','#ea70bc','#efb94f'].map(c=>'<button type="button" data-author-color="'+c+'" style="color:'+c+'" title="'+c+'" aria-label="Couleur '+c+'"><span class="warlink-author-mark"></span></button>').join('')}</div></div></div>
                    ${field('gamePath','Dossier HorizonMW (hmw-mod.exe)','text',p.gamePath,'required')}
                    ${field('port','Port du serveur · TCP et UDP','number',p.port,'min="1024" max="65535" required')}
                    ${field('password','Mot de passe pour rejoindre (privé)','text',p.password,'maxlength="64" autocomplete="off"')}
                    ${field('players','Places, humains et bots compris','number',p.players,'min="2" max="18" required')}
                    <label class="hmwh-field"><span>Mode de jeu</span><select name="mode"><option value="mix">Mix · plusieurs modes</option>${Object.entries(modes).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label>
                    <div class="hmwh-mix-modes" style="grid-column:1/-1" ${p.mode==='mix'?'':'hidden'}><h4>Modes du Mix</h4><div class="hmwh-grid">${Object.entries(modes).map(([id,label])=>`<label><input type="checkbox" data-mix-mode value="${id}" ${(p.mixModes||['war','dom']).includes(id)?'checked':''}> ${label}</label>`).join('')}</div><p class="hmwh-muted">Chaque carte est jouée avec les modes cochés dans cet ordre, puis la rotation passe à la carte suivante. Désactive le vote de carte pour respecter la rotation. Choisis des cartes compatibles avec ces modes.</p></div>
                    ${field('discord','Lien Discord affiché en jeu','text',p.discord||'','maxlength="160" placeholder="https://discord.gg/..."')}
                    ${field('announcement','Annonce périodique en jeu','text',p.announcement||'','maxlength="160"')}
                    ${field('announcementInterval','Annonces en secondes (0 = désactivé, minimum 10 s)','number',p.announcementInterval||0,'min="0" max="3600"')}
                </div>
                <h3>Accueil · première apparition</h3><div class="hmwh-grid">
                    ${field('motd','Message à l’arrivée dans la partie','text',p.motd,'maxlength="160"')}
                    <label class="hmwh-field"><span>Position du message d’accueil et des annonces</span><select name="messagePosition"><option value="chat">Bas à gauche · messages du jeu</option><option value="center">Centre · grand message</option><option value="left">Milieu à gauche · bandeau</option></select></label>
                </div><p class="hmwh-muted">Le message d’accueil et le Discord sont affichés une seule fois à l’arrivée dans la partie.</p>
                <h3>Réapparition · message distinct</h3><div class="hmwh-grid">
                    ${field('respawnMessage','Message à chaque réapparition (vide = désactivé)','text',p.respawnMessage,'maxlength="160"')}
                    <label class="hmwh-field"><span>Position du message de réapparition</span><select name="respawnPosition"><option value="chat">Bas à gauche · messages du jeu</option><option value="center">Centre · grand message</option><option value="left">Milieu à gauche · bandeau</option></select></label>
                </div>
                <h3>▦ Cartes & rotation</h3><div class="hmwh-map-editor"><input type="hidden" name="rotation" value="${esc(p.rotation.join(' '))}"><div class="hmwh-map-tools"><select data-map-family aria-label="Origine des cartes"><option value="">Toutes les cartes</option><option value="MWR">Modern Warfare Remastered</option><option value="MW2">Modern Warfare 2</option><option value="MW3">Modern Warfare 3</option><option value="custom">Autres cartes</option></select><input type="search" data-map-search placeholder="Rechercher une carte…" aria-label="Rechercher une carte"><button type="button" data-map-all>Tout sélectionner</button><button type="button" data-map-none>Tout désélectionner</button></div><div class="hmwh-map-catalog"></div><h4>Ordre de la rotation <small class="hmwh-map-count"></small></h4><div class="hmwh-map-rotation"></div><p class="hmwh-muted">Déplace les cartes avec les flèches. Seules les cartes détectées dans ton installation sont proposées. Les visuels des 57 cartes sont extraits des fichiers de chargement du jeu et disponibles hors ligne.</p></div>
                <h3>◈ Bots & équipes</h3><div class="hmwh-grid">
                    ${field('humans','Places réservées aux humains','number',Math.max(1,p.players-p.bots),'min="1" max="18" required')}
                    ${field('bots','Nombre de bots (0 = sans bots)','number',p.bots,'min="0" max="17" required')}
                    <label class="hmwh-field"><span>Difficulté</span><select name="difficulty"><option value="recruit">Recrue</option><option value="regular">Normal</option><option value="hardened">Vétéran</option><option value="veteran">Expert</option><option value="mixed">Mélangée</option></select></label>
                    <label class="hmwh-field"><span>Équipement des bots</span><select name="botWeapons"><option value="mixed">Mix · classes du jeu</option><option value="sniper">Snipers variés · rotation à chaque vie</option><option value="knife">Mêlée uniquement · sans munitions</option><option value="none">Sans arme</option></select></label><p class="hmwh-muted">Les clans et pseudos se règlent dans l’onglet Identité des bots.</p><label><input name="botBalance" type="checkbox" ${p.botBalance?'checked':''}> Rééquilibrer les équipes avec les bots</label>
                </div><p class="hmwh-muted hmwh-allocation" aria-live="polite"></p><p class="hmwh-muted">Les bots libèrent des places quand des humains rejoignent. Certaines cartes personnalisées n’ont pas de navigation pour les bots. En mode sniper, les armes valides du catalogue sont réparties entre les bots et changent à leurs réapparitions. Le multiplicateur XP se règle dans Règles de partie ; la sauvegarde de progression dépend du client de jeu.</p>
                <h3>⚑ Règles de partie</h3><div class="hmwh-grid"><label class="hmwh-field"><span>Expérience des joueurs</span><select name="xpMultiplier"><option value="1">XP normale · ×1</option><option value="2">Double XP · ×2</option><option value="4">XP ×4 · test</option></select></label>
                    ${field('scoreLimit','Limite de score (0 = illimité)','number',p.scoreLimit,'min="0" max="100000"')}
                    ${field('timeLimit','Durée en minutes (0 = illimité)','number',p.timeLimit,'min="0" max="1440"')}
                    ${field('health','Santé des joueurs','number',p.health,'min="1" max="1000"')}
                    <label class="hmwh-field"><span>Tir allié</span><select name="friendlyFire"><option value="0">Désactivé</option><option value="1">Activé</option><option value="2">Renvoi des dégâts</option><option value="3">Partagé</option></select></label>
                </div><div class="hmwh-checks">${[['killstreaks','Séries d’éliminations'],['voting','Votes'],['headshots','Tirs à la tête uniquement'],['allowTeamChange','Autoriser le choix et le changement d’équipe']].map(([id,label])=>`<label><input type="checkbox" name="${id}" ${p[id]?'checked':''}> ${label}</label>`).join('')}</div>
                <p class="hmwh-muted">Changement d’équipe : utilise « Équipes des joueurs » à droite. Le menu Échap du jeu peut rester masqué selon le client. Les humains gardent leur choix ; active le rééquilibrage des bots pour compléter les équipes.</p><details><summary>Règles supplémentaires</summary><div class="hmwh-grid">
                    ${field('healthRegen','Régénération santé (secondes)','number',p.healthRegen,'min="0" max="120"')}
                    ${field('respawnDelay','Délai de réapparition (secondes)','number',p.respawnDelay,'min="0" max="120"')}
                    ${field('lives','Vies par joueur (0 = illimité)','number',p.lives,'min="0" max="100"')}
                    ${field('roundLimit','Limite de manches (0 = illimité)','number',p.roundLimit,'min="0" max="100"')}
                    ${field('winLimit','Manches à gagner','number',p.winLimit,'min="0" max="100"')}
                </div><div class="hmwh-checks">${[['hardcore','Hardcore'],['constantUav','Radar permanent'],['disableSprint','Désactiver le sprint'],['thirdPerson','Troisième personne'],['collision','Collision entre joueurs']].map(([id,label])=>`<label><input type="checkbox" name="${id}" ${p[id]?'checked':''}> ${label}</label>`).join('')}</div><p class="hmwh-muted">Les règles disponibles peuvent varier selon la carte et le mode. La section CFG permet les commandes supplémentaires du moteur.</p></details>
                <details><summary>Administration & paramètres avancés</summary><div class="hmwh-grid">
                    ${field('rconPassword','Mot de passe RCON (généré si vide)','password',p.rconPassword,'maxlength="64" autocomplete="off"')}
                    ${field('serverKey','Clé officielle de référencement (si fournie par HMW)','password',p.serverKey,'maxlength="256" autocomplete="off"')}
                </div><label class="hmwh-field"><span>Configuration CFG supplémentaire · appliquée au démarrage après les réglages ci-dessus</span><textarea name="advanced" rows="6" spellcheck="false">${esc(p.advanced)}</textarea></label><p class="hmwh-muted">Les commandes dépendent de la version d’HorizonMW. Un changement de configuration nécessite un redémarrage.</p></details>
                <button class="hmwh-primary" type="submit">Enregistrer le serveur</button>
            </form>`;
        decorateHost();
        const form=overlay.querySelector('form');
        window.WarlinkName.mount(form);
        for(const k of ['access','mode','difficulty','friendlyFire','messagePosition','respawnPosition','botWeapons','xpMultiplier'])form.elements[k].value=String(p[k]);
        overlay.querySelector('.hmwh-live-map').innerHTML=maps.map(m=>`<option value="${esc(m)}">${esc(mapLabel(m))}</option>`).join('');
        renderMaps();
        syncAllocation();
        renderList();overlay.querySelector('.hmwh-log').textContent='Démarre le serveur puis consulte ici son chargement.';
        overlay.querySelector('.hmwh-status').textContent=profile?'Serveur sélectionné':'Nouveau profil · à enregistrer';
    }
    async function refreshList(){const r=await api('list');profiles=r.profiles;maps=r.maps;gamePath=r.gamePath;renderList();window.dispatchEvent(new Event('warlink-hmw-profiles-changed'));}
    async function poll(){
        if(!overlay||!selected||polling||busy||!current())return;
        const id=selected;
        if(clientPanel()&&!clientPanel().hidden&&Date.now()-clientUpdated>5000){try{await refreshClients();await refreshBans();}catch{}}
        polling=true;try{
            const r=await api('status',{id});
            if(!overlay||id!==selected)return;
            overlay.querySelector('.hmwh-status').textContent=r.ready?'● En ligne · prêt à rejoindre':r.running?'◌ Démarrage / chargement de la carte…':'○ Arrêté';
            overlay.querySelector('.hmwh-status').classList.toggle('ready',!!r.ready);
            overlay.querySelector('.hmwh-info').textContent=r.info?r.info.replace(/^infoResponse\s*/,'').replace(/\\/g,' · '):'';
            overlay.querySelector('.hmwh-publishing').textContent='Communauté WARLINK : publication après vérification du port '+current().port+' en TCP et UDP depuis Internet. La liste officielle du jeu est indépendante.';
            for(const b of overlay.querySelectorAll('.hmwh-controls [data-action]'))b.disabled=b.dataset.action==='start'?!!r.running:!r.running;overlay.querySelector('.hmwh-controls [data-join]').disabled=!r.ready;
            const share=overlay.querySelector('.hmwh-share-address');share.textContent=r.shareEndpoint?'connect '+r.shareEndpoint:'Adresse non publiée';overlay.querySelector('[data-copy-connect="share"]').disabled=!r.shareEndpoint;overlay.querySelector('.hmwh-share-help').textContent=r.shareEndpoint?'À transmettre à tes amis. Le mot de passe se saisit séparément dans le jeu.':'Publie ce serveur pour obtenir son adresse Internet. L’adresse 127.0.0.1 fonctionne uniquement sur ce PC.';
            const log=overlay.querySelector('.hmwh-log');if(r.log){const atBottom=log.scrollHeight-log.scrollTop-log.clientHeight<60;log.innerHTML=colorLog(r.log);if(atBottom)log.scrollTop=log.scrollHeight;}
        }catch(e){message(e.message,true);}finally{polling=false;}
    }
    async function act(action){
        if(busy)return;
        if(!selected||!current())throw Error('Enregistre d’abord un profil serveur.');
        busy=true;try{message('Opération en cours…');await api(action,{id:selected});window.dispatchEvent(new Event('warlink-hmw-profiles-changed'));message(action==='start'?'Démarrage lancé. Le premier chargement peut prendre plusieurs minutes.':action==='stop'?'Serveur arrêté.':'Redémarrage lancé.');}finally{busy=false;}
        await poll();
    }
    async function rcon(command){const r=await api('rcon',{id:selected,command});overlay.querySelector('.hmwh-rcon-output').textContent=r.output||'';}
    function clientPanel(){return overlay?.querySelector('.hmwh-clients');}
    function currentClient(){return clients.find(p=>p.guid===clientSelection);}
    async function refreshClients(){
        if(clientRefresh||!selected)return;clientRefresh=true;
        try{const r=await api('team-players',{id:selected});clients=r.players;if(!clients.some(p=>p.guid===clientSelection))clientSelection=clients[0]?.guid||null;
            const host=clientPanel();if(!host)return;host.querySelector('[data-client-count]').textContent=clients.length+' humain(s) · '+(r.bots||0)+' bot(s) · '+(clients.length+(r.bots||0))+' clients';
            host.querySelector('.hmwh-client-list').innerHTML=clients.map(p=>'<button type="button" data-client="'+esc(p.guid)+'" class="'+(p.guid===clientSelection?'active':'')+'"><strong>'+esc(p.name)+'</strong><small>Place '+p.slot+'</small></button>').join('')||'<p>Aucun joueur humain connecté.</p>';
            host.querySelector('[data-client-name]').textContent=currentClient()?.name||'Sélectionne un joueur';clientUpdated=Date.now();
        }finally{clientRefresh=false;}
    }
    async function refreshBans(){const r=await api('moderation-list',{id:selected});const host=clientPanel();if(!host)return;host.querySelector('.hmwh-ban-list').innerHTML=r.bans.map(p=>'<div class="hmwh-ban-row"><div><strong>'+esc(p.name)+'</strong><small>'+esc(p.expires===-1?'Bannissement permanent':'Jusqu’au '+new Date(p.expires*1000).toLocaleString())+'</small><p>'+esc(p.reason)+'</p></div><button type="button" data-unban="'+esc(p.guid)+'">Lever l’exclusion</button></div>').join('')||'<p>Aucune exclusion active.</p>';}
    function renderClients(){const host=clientPanel();host.innerHTML='<div class="hmwh-section-head"><h3>Joueurs connectés</h3><button type="button" data-client-refresh>Actualiser</button></div><p data-client-count>Chargement…</p><div class="hmwh-client-list"></div><h3 data-client-name>Sélectionne un joueur</h3><div class="hmwh-grid"><label class="hmwh-field"><span>Pseudo de session</span><input data-client-newname maxlength="24" placeholder="Modification en jeu non prise en charge" disabled><button type="button" data-client-rename disabled>Renommage en jeu indisponible</button><small>Le test ne synchronise pas le pseudo du client : cette action est désactivée.</small></label><label class="hmwh-field"><span>Clan tag</span><input disabled placeholder="Non pris en charge par le client actuel"><small>La modification du véritable clan tag n’est pas encore validée. Aucun changement de profil n’est effectué.</small></label></div><h3>Modération sur ce serveur</h3><label class="hmwh-field"><span>Motif communiqué au joueur</span><input data-client-reason maxlength="120" placeholder="Ex. : insultes répétées"></label><div class="hmwh-grid"><label class="hmwh-field"><span>Durée d’exclusion</span><select data-client-duration><option value="300">5 minutes</option><option value="3600" selected>1 heure</option><option value="86400">24 heures</option><option value="604800">7 jours</option></select></label><label class="hmwh-field"><span>Équipe du joueur sélectionné</span><select data-client-team><option value="allies">Alliés</option><option value="axis">Axe</option></select><button type="button" data-client-team-apply>Changer l’équipe</button></label></div><div class="hmwh-moderation-actions"><button type="button" data-moderate="kick">Kicker</button><button type="button" data-moderate="temporary">Exclure temporairement</button><button type="button" data-moderate="ban" class="hmwh-danger">Bannir</button></div><p class="hmwh-muted">Kick : retour autorisé. Exclusion : retour bloqué jusqu’à expiration. Bannissement : retour bloqué jusqu’à révocation. Les exclusions suivent l’identité HMW et restent actives lorsque WARLINK est fermé.</p><details open><summary>Exclusions actives</summary><div class="hmwh-ban-list"></div></details>';}
    function renderProgression(){overlay.querySelector('.hmwh-progression').innerHTML='<h3>Événements XP</h3><p>Le multiplicateur est enregistré dans ce serveur et appliqué automatiquement à chaque démarrage et changement de carte, pour tous les joueurs.</p><label class="hmwh-field"><span>Expérience des joueurs</span><select data-progression-xp><option value="1">XP normale ×1</option><option value="2">Double XP ×2</option><option value="4">XP ×4 · test</option></select></label><button type="button" data-progression-apply>Enregistrer et appliquer</button><p class="hmwh-muted">Choisis ×2 pour ton événement, puis ×1 à la fin. Les niveaux, prestiges et déblocages restent dans le menu Stats du jeu.</p>';overlay.querySelector('[data-progression-xp]').value=String(current()?.xpMultiplier||1);}
    let identityBots=[];
    async function renderBotIdentities(){
        const host=overlay.querySelector('.hmwh-identities'),id=selected;
        const r=await api('bot-identities',{id});if(!overlay||id!==selected)return;
        identityBots=r.bots||[];const settings=r.settings||{};
        host.innerHTML=`<h3>Identité des bots</h3><p class="hmwh-muted">Listes sauvegardées pour ce serveur. Un clan et un pseudo sont associés aléatoirement, sans doublons d’identité. Une liste de pseudos vide conserve les noms actuels.</p><div class="hmwh-grid"><label class="hmwh-field"><span>Clans · un par ligne, sans crochets</span><textarea data-bot-tags rows="7" placeholder="WLK\nZXG\nFRA">${esc((settings.tags||[]).join('\n'))}</textarea><small>8 caractères maximum par clan.</small></label><label class="hmwh-field"><span>Pseudos · un par ligne</span><textarea data-bot-names rows="7" placeholder="Ghost\nPrice\nSoap">${esc((settings.names||[]).join('\n'))}</textarea><small>20 caractères maximum. Lettres sans accents, chiffres, espaces, point, tiret et underscore.</small></label></div><label class="hmwh-bot-auto"><input type="checkbox" data-bot-auto ${settings.enabled?'checked':''}> Appliquer automatiquement aux nouveaux bots</label><p class="hmwh-muted">L’automatisation reste active tant que WARLINK est ouvert. Les identités déjà appliquées restent en jeu après sa fermeture.</p><div class="hmwh-identity-actions"><button type="button" data-bot-save>Enregistrer les listes</button><button type="button" data-bot-shuffle>Mélanger et appliquer à tous</button></div><h3>Bots connectés · ${identityBots.length}</h3><div class="hmwh-section-head"><span class="hmwh-muted">Sélectionne un bot pour modifier son identité de session.</span><button type="button" data-bot-refresh>Actualiser</button></div><div class="hmwh-bot-list">${identityBots.map(p=>`<button type="button" data-bot-slot="${p.slot}"><span>${esc(p.identity)}</span><small>Place ${p.slot+1}</small></button>`).join('')||'<p>Aucun bot actif. Démarre un serveur avec des bots.</p>'}</div><div class="hmwh-bot-single" hidden><h3 data-bot-selected></h3><div class="hmwh-grid"><label class="hmwh-field"><span>Clan</span><input data-bot-tag maxlength="8"></label><label class="hmwh-field"><span>Pseudo</span><input data-bot-name maxlength="20"></label></div><button type="button" data-bot-apply>Appliquer à ce bot</button></div>`;
    }
    const botList=value=>value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
    async function saveBotLists(){const r=await api('bot-identities-save',{id:selected,settings:{enabled:overlay.querySelector('[data-bot-auto]').checked,tags:botList(overlay.querySelector('[data-bot-tags]').value),names:botList(overlay.querySelector('[data-bot-names]').value)}});message(r.message);}
    async function workPanel(name){overlay.querySelector(".hmwh-identities").hidden=name!=="identities";overlay.querySelector('.hmwh-editor').hidden=name!=='config';clientPanel().hidden=name!=='clients';overlay.querySelector('.hmwh-progression').hidden=name!=='progression';for(const b of overlay.querySelectorAll('[data-work]'))b.classList.toggle('active',b.dataset.work===name);if(name==='clients'){renderClients();await refreshClients();await refreshBans();}if(name==='progression')renderProgression();if(name==='identities')await renderBotIdentities();decorateHost();}
    async function open(profileId){
        if(overlay)return;
        overlay=document.createElement('div');overlay.className='hmwh-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Mes serveurs HorizonMW');
        overlay.innerHTML=`<div class="hmwh-window"><header><div><span class="hmwh-eyebrow">WARLINK / HORIZONMW</span><h2>Mes serveurs</h2></div><button type="button" data-close aria-label="Fermer le gestionnaire">✕</button></header>
            ${preview?'<p class="hmwh-preview">Aperçu de l’interface : aucun serveur n’est lancé depuis ce navigateur.</p>':''}
            <div class="hmwh-body"><aside><button type="button" data-new>＋ Créer un serveur</button><div class="hmwh-profiles"></div><p class="hmwh-muted">Privé ou public, le serveur reste actif tant que ton PC est allumé. Fermer WARLINK ne l’arrête pas.</p><p class="hmwh-muted">Pour tes amis : autoriser le port choisi en TCP et UDP dans le pare-feu et sur la box. Chaque serveur simultané exige un port différent et sa propre redirection. Aucune clé HMW n’est nécessaire pour la communauté WARLINK.</p></aside>
            <main><div class="hmwh-message" role="status"></div><nav class="hmwh-work-nav"><button type="button" data-work="config" class="active">Configuration</button><button type="button" data-work="clients">Joueurs & modération</button><button type="button" data-work="identities">Identité des bots</button><button type="button" data-work="progression">Événements XP</button><button type="button" class="hmwh-quick-save" data-quick-save title="Enregistrer le serveur" aria-label="Enregistrer le serveur"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 3h13l4 4v14H3V3h1Z"/><path d="M7 3v6h10V3M7 21v-8h10v8"/></svg></button></nav><div class="hmwh-editor"></div><div class="hmwh-clients" hidden></div><div class="hmwh-progression" hidden></div><div class="hmwh-identities" hidden></div></main>
            <section class="hmwh-monitor"><div class="hmwh-discord-auth"><strong>Publication · compte Discord</strong><p class="hmwh-auth-name hmwh-muted">VIP, STAFF ou ADMINS requis pour publier.</p><button type="button" data-auth-login>Se connecter avec Discord</button><button type="button" data-auth-logout hidden>Déconnexion</button></div><details class="hmwh-action-section hmwh-publication-top" open><summary><img src="assets/img/brand/warlink-mark-white.svg" alt="" width="34" height="18"> Publication WARLINK</summary><div class="hmwh-action-grid"><button type="button" data-publish><svg class="hmwh-button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/></svg><span>Publier le serveur</span></button><button type="button" data-unpublish><svg class="hmwh-button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/></svg><span>Retirer le serveur</span></button></div><button type="button" data-network class="hmwh-full">Guide réseau & publication</button></details><h3>Contrôle du serveur</h3><strong class="hmwh-status">Sélectionne un serveur</strong>
                <div class="hmwh-controls"><button type="button" data-action="start"><svg class="hmwh-button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m8 5 11 7-11 7Z"/></svg><span>Démarrer</span></button><button type="button" data-join class="hmwh-primary"><svg class="hmwh-button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M3 12h13m-5-5 5 5-5 5M17 4h4v16h-4"/></svg><span>Rejoindre</span></button><button type="button" data-action="restart"><svg class="hmwh-button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20 7v5h-5M20 12a8 8 0 1 0-2 6"/></svg><span>Redémarrer</span></button><button type="button" data-action="stop"><svg class="hmwh-button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="6" y="6" width="12" height="12"/></svg><span>Arrêter</span></button></div>
                <div class="hmwh-connect-block"><span>Connexion sur ce PC</span><div class="hmwh-connect-row"><code class="hmwh-address"></code><button type="button" data-copy-connect="local" aria-label="Copier la commande locale" title="Copier la commande locale"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="8" width="12" height="13" rx="1"></rect><path d="M16 8V3H3v13h5"></path></svg></button></div><span>Adresse Internet à partager</span><div class="hmwh-connect-row"><code class="hmwh-share-address">Adresse non publiée</code><button type="button" data-copy-connect="share" aria-label="Copier la commande à partager" title="Copier la commande à partager" disabled><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="8" y="8" width="12" height="13" rx="1"></rect><path d="M16 8V3H3v13h5"></path></svg></button></div><p class="hmwh-share-help hmwh-muted">Publie ce serveur sur WARLINK pour obtenir son adresse Internet.</p></div>
                <p class="hmwh-publishing hmwh-muted"></p>
                <div class="hmwh-action-section"><h3>Joueurs</h3><button type="button" data-work="clients" class="hmwh-full">Gérer les joueurs et les équipes</button></div>
                <div class="hmwh-action-section"><h3>Partie & cartes</h3><div class="hmwh-action-grid"><button type="button" data-cmd="map_rotate">Carte suivante</button><button type="button" data-cmd="map_restart">Relancer la partie</button></div><label class="hmwh-field"><span>Changer de carte</span><select class="hmwh-live-map" aria-label="Carte à charger"></select></label><button type="button" data-map class="hmwh-full">Charger la carte sélectionnée</button></div>
                <details class="hmwh-action-section" open><summary>Appliquer les réglages</summary><div class="hmwh-action-grid"><button type="button" data-bots>Bots</button><button type="button" data-teams>Choix d’équipe</button><button type="button" data-xp>Multiplicateur XP</button><button type="button" data-banner>Tester le bandeau</button></div></details>

                <details class="hmwh-action-section" open><summary>Annonce à tous les joueurs</summary><label class="hmwh-field"><span>Message au centre de l’écran</span><input data-live-text maxlength="120" placeholder="Ex. : Changement de carte dans un instant…"></label><label class="hmwh-field" style="margin-top:12px"><span>Durée d’affichage</span><select data-live-duration><option value="2">2 secondes</option><option value="3">3 secondes</option><option value="5" selected>5 secondes</option><option value="10">10 secondes</option></select></label><button type="button" data-live-send style="margin-top:16px;width:100%">Envoyer à tous les joueurs</button></details>
                <details class="hmwh-action-section"><summary>Console administrateur</summary><form class="hmwh-rcon-form"><label class="hmwh-field"><span>Commande RCON</span><input name="command" placeholder="status, map mp_rust…" autocomplete="off"></label><button type="submit">Envoyer</button></form><pre class="hmwh-rcon-output"></pre></details>
                <h3>Journal de démarrage</h3><div class="hmwh-log-legend"><span class="hmwh-log-error">Erreur</span><span class="hmwh-log-warn">Avertissement</span><span class="hmwh-log-success">Succès</span><span class="hmwh-log-map">Carte</span><span class="hmwh-log-asset">Ressource</span></div><pre class="hmwh-log"></pre><details><summary>Réponse réseau</summary><pre class="hmwh-info"></pre></details>
            </section></div></div>`;
        document.body.appendChild(overlay);
        decorateHost();
        const run=fn=>Promise.resolve().then(fn).catch(e=>message(e.message,true));
        overlay.addEventListener('click',event=>{
            const b=event.target.closest('button');if(!b)return;if(busy&&!b.hasAttribute('data-close'))return;
            if(b.dataset.copyConnect){run(async()=>{const value=overlay.querySelector(b.dataset.copyConnect==='share'?'.hmwh-share-address':'.hmwh-address').textContent;if(!value.startsWith('connect '))throw Error('Adresse indisponible.');if(!await window.copyTextToClipboard(value.replace(/^connect\s+/,'').trim()))throw Error('La copie a échoué.');window.showToast(b.dataset.copyConnect==='share'?'Adresse Internet copiée, prête à partager.':'Adresse locale copiée.','success');});return;}
            if(b.hasAttribute('data-bot-slot')){const bot=identityBots.find(p=>p.slot===Number(b.dataset.botSlot));if(!bot)return;const box=overlay.querySelector('.hmwh-bot-single');box.hidden=false;box.dataset.slot=bot.slot;overlay.querySelector('[data-bot-selected]').textContent=bot.identity;overlay.querySelector('[data-bot-tag]').value=bot.tag;overlay.querySelector('[data-bot-name]').value=bot.name;for(const item of overlay.querySelectorAll('[data-bot-slot]'))item.classList.toggle('active',item===b);return;}
            if(b.hasAttribute('data-bot-refresh')){run(renderBotIdentities);return;}
            if(b.hasAttribute('data-bot-save')){run(async()=>{await saveBotLists();await renderBotIdentities();});return;}
            if(b.hasAttribute('data-bot-shuffle')){run(async()=>{await saveBotLists();const r=await api('bot-identities-shuffle',{id:selected});message(r.message);await renderBotIdentities();});return;}
            if(b.hasAttribute('data-bot-apply')){run(async()=>{const slot=Number(overlay.querySelector('.hmwh-bot-single').dataset.slot),bot=identityBots.find(p=>p.slot===slot);if(!bot)throw Error('Sélectionne un bot');const r=await api('bot-identity-set',{id:selected,slot,expected:bot.identity,tag:overlay.querySelector('[data-bot-tag]').value.trim(),name:overlay.querySelector('[data-bot-name]').value.trim()});message(r.message);await renderBotIdentities();});return;}
            if(b.dataset.work){run(()=>workPanel(b.dataset.work));return;}
            if(b.dataset.client){clientSelection=b.dataset.client;run(refreshClients);return;}
            if(b.hasAttribute('data-client-refresh')){run(async()=>{await refreshClients();await refreshBans();});return;}
            if(b.dataset.unban){run(async()=>{const c=await window.showMessageBox('Lever l’exclusion','Ce joueur pourra revenir sur ce serveur.',['Annuler','Lever']);if(c!==1)return;const r=await api('unban',{id:selected,guid:b.dataset.unban});message(r.message);await refreshBans();});return;}
            if(b.dataset.moderate){run(async()=>{const p=currentClient();if(!p)throw Error('Sélectionne un joueur connecté.');const kind=b.dataset.moderate,seconds=Number(overlay.querySelector('[data-client-duration]').value),reason=overlay.querySelector('[data-client-reason]').value||'Modération WARLINK';const c=await window.showMessageBox('Modérer '+p.name+' · place '+p.slot,esc(kind==='kick'?'Expulser ce joueur ? Il pourra revenir.':kind==='temporary'?'Exclure ce joueur pendant '+(seconds/60)+' minutes ?':'Bannir ce joueur de ce serveur jusqu’à révocation ?'),['Annuler','Confirmer']);if(c!==1)return;busy=true;try{const r=await api('moderate',{id:selected,slot:p.slot,guid:p.guid,kind,seconds,reason});message(r.message);}finally{busy=false;await refreshClients();await refreshBans();}});return;}
            if(b.hasAttribute('data-client-rename')){run(async()=>{const p=currentClient();if(!p)throw Error('Sélectionne un joueur.');const r=await api('moderate',{id:selected,slot:p.slot,guid:p.guid,kind:'rename',value:overlay.querySelector('[data-client-newname]').value});message(r.message);await refreshClients();});return;}
            if(b.hasAttribute('data-client-team-apply')){run(async()=>{const p=currentClient();if(!p)throw Error('Sélectionne un joueur.');const r=await api('team-move',{id:selected,slot:p.slot,guid:p.guid,team:overlay.querySelector('[data-client-team]').value});message(r.message);});return;}
            if(b.hasAttribute('data-progression-apply')){run(async()=>{const multiplier=Number(overlay.querySelector('[data-progression-xp]').value),r=await api('xp-update',{id:selected,multiplier});if(current())current().xpMultiplier=multiplier;overlay.querySelector('[name=xpMultiplier]').value=String(multiplier);message(r.message);});return;}
            if(b.hasAttribute('data-network'))window.WarlinkNetworkGuide.open(selected);
            if(b.hasAttribute('data-map-all')){setRotation(maps);return;}
            if(b.hasAttribute('data-map-none')){setRotation([]);return;}
            if(b.dataset.rotation){const a=rotation(),i=Number(b.dataset.index),j=i+Number(b.dataset.rotation);if(j>=0&&j<a.length){[a[i],a[j]]=[a[j],a[i]];setRotation(a);}return;}
            if(b.dataset.removeMap){setRotation(rotation().filter(m=>m!==b.dataset.removeMap));return;}
            if(b.hasAttribute('data-close')){clearInterval(timer);overlay.remove();overlay=null;return;}
            if(b.hasAttribute('data-new')){selected='srv_'+Date.now().toString(36);renderForm();workPanel('config');message('Choisis un préréglage, ajuste les options puis enregistre.');return;}
            if(b.dataset.profile){clientSelection=null;clients=[];clientUpdated=0;selected=b.dataset.profile;identityBots=[];renderForm(current());message('');updateAddress();run(async()=>{await poll();if(!clientPanel().hidden){await refreshClients();await refreshBans();}if(!overlay.querySelector('.hmwh-identities').hidden)await renderBotIdentities();if(!overlay.querySelector('.hmwh-progression').hidden)renderProgression();});}
            if(b.dataset.action)run(()=>act(b.dataset.action));
            if(b.dataset.cmd)run(()=>rcon(b.dataset.cmd));
            if(b.hasAttribute('data-map'))run(()=>{const map=overlay.querySelector('.hmwh-live-map').value;if(!/^[a-zA-Z0-9_]+$/.test(map))throw Error('Choisis une carte.');return rcon('map '+map);});
            if(b.hasAttribute('data-teams'))run(()=>{const p=values();return rcon('set warlink_allow_team_change '+(p.allowTeamChange?1:0)+'; set scr_teambalance '+(p.allowTeamChange||p.botBalance?0:1));});
            if(b.hasAttribute('data-xp'))run(async()=>{const multiplier=values().xpMultiplier,r=await api('xp-update',{id:selected,multiplier});if(current())current().xpMultiplier=multiplier;message(r.message);});
            if(b.hasAttribute('data-live-send'))run(async()=>{const text=overlay.querySelector('[data-live-text]').value.trim();if(!text)throw Error('Saisis un message.');if(/[";\\\r\n]/.test(text))throw Error('Les guillemets, points-virgules et retours à la ligne ne sont pas acceptés.');const duration=Number(overlay.querySelector('[data-live-duration]').value);if(![2,3,5,10].includes(duration))throw Error('Durée invalide.');await rcon('set warlink_live_text "'+text+'"; set warlink_live_duration '+duration+'; set warlink_live_send 1');message('Annonce envoyée à tous les joueurs · '+duration+' secondes.');});
            if(b.hasAttribute('data-banner'))run(()=>rcon('set warlink_test_banner 1'));
            if(b.hasAttribute('data-bots'))run(()=>{const p=values();if(p.bots>p.players-1)throw Error('Il faut réserver au moins une place pour un joueur.');return rcon(`set warlink_bot_count ${p.bots}; set warlink_bot_difficulty ${p.difficulty}; set warlink_bot_weapons ${p.botWeapons}; set warlink_bot_balance ${p.botBalance?1:0}`);});
            if(b.hasAttribute('data-author-palette')){const input=overlay.querySelector('[name=authorColor]'),dialog=document.createElement('div');dialog.className='hmwh-color-overlay';const initial=input.value;dialog.innerHTML='<section class="hmwh-color-dialog"><header><div><small>WARLINK / PERSONNALISATION</small><h3>Couleur du logo</h3></div><button type="button" data-color-close aria-label="Fermer">✕</button></header><div class="hmwh-color-preview"><span class="warlink-author-mark"></span></div>'+[['r','Rouge'],['g','Vert'],['b','Bleu']].map(([k,label],i)=>'<label>'+label+'<input type="range" data-rgb="'+k+'" min="0" max="255" value="'+parseInt(initial.slice(1+i*2,3+i*2),16)+'"></label>').join('')+'<label>Code couleur HEX<input data-hex value="'+initial+'" maxlength="7" spellcheck="false"></label><footer><button type="button" data-color-cancel>Annuler</button><button type="button" data-color-apply>Appliquer</button></footer></section>';const hex=dialog.querySelector('[data-hex]'),preview=dialog.querySelector('.warlink-author-mark');const update=()=>preview.style.color=hex.value;update();dialog.addEventListener('input',e=>{if(e.target.hasAttribute('data-rgb'))hex.value='#'+Array.from(dialog.querySelectorAll('[data-rgb]'),x=>Number(x.value).toString(16).padStart(2,'0')).join('');if(/^#[a-f0-9]{6}$/i.test(hex.value)){Array.from(dialog.querySelectorAll('[data-rgb]')).forEach((x,i)=>x.value=parseInt(hex.value.slice(1+i*2,3+i*2),16));update();}});dialog.querySelector('[data-color-cancel]').onclick=()=>dialog.remove();dialog.querySelector('[data-color-close]').onclick=()=>dialog.remove();dialog.querySelector('[data-color-apply]').onclick=()=>{if(!/^#[a-f0-9]{6}$/i.test(hex.value)){hex.focus();return;}input.value=hex.value;dialog.remove();};overlay.append(dialog);return;}
            if(b.dataset.authorColor){overlay.querySelector('[name=authorColor]').value=b.dataset.authorColor;return;}
            if(b.hasAttribute('data-quick-save')){overlay.querySelector('.hmwh-form')?.requestSubmit();return;}
            if(b.hasAttribute('data-auth-login'))run(async()=>{const r=await api('auth-start');await window.executeCommand('open-url',{url:r.authorizationUrl});message('Termine la connexion dans ton navigateur.');const deadline=Date.now()+300000;while(overlay?.isConnected&&Date.now()<deadline){await new Promise(r=>setTimeout(r,2000));const state=await api('auth-poll');if(state.authorized){overlay.querySelector('.hmwh-auth-name').textContent='Connecté : '+state.displayName;overlay.querySelector('[data-auth-login]').hidden=true;overlay.querySelector('[data-auth-logout]').hidden=false;message('Connexion validée : publication autorisée.');return;}}throw Error('Connexion expirée.');});
            if(b.hasAttribute('data-auth-logout'))run(async()=>{await api('auth-logout');overlay.querySelector('.hmwh-auth-name').textContent='Déconnecté';overlay.querySelector('[data-auth-login]').hidden=false;overlay.querySelector('[data-auth-logout]').hidden=true;});
            if(b.hasAttribute('data-publish'))run(async()=>{const choice=await window.showMessageBox('Publier dans la communauté WARLINK','Ton adresse IP publique, le port, le nom du serveur, la carte et le nombre de joueurs seront visibles aux utilisateurs WARLINK. Les mots de passe ne sont pas publiés.',['Annuler','Publier']);if(choice!==1)return;let r;try{r=await api('publish',{id:selected,author:overlay.querySelector('[name=author]').value.trim(),authorColor:overlay.querySelector('[name=authorColor]').value});}catch(e){if(/port|UDP|TCP|répond|adresse publique/i.test(e.message))networkHelp(e.message);else message(e.message,true);return;}message(r.message);await window.ServersView.refreshCommunity();});
            if(b.hasAttribute('data-unpublish'))run(async()=>{const r=await api('unpublish',{id:selected});message(r.message);window.dispatchEvent(new Event('warlink-hmw-profiles-changed'));});
            if(b.hasAttribute('data-join'))run(async()=>{if(!current())throw Error('Choisis un profil enregistré.');const result=await api('join',{id:selected});message(result.message);});
        });
        overlay.addEventListener('submit',event=>{event.preventDefault();if(event.target.classList.contains('hmwh-rcon-form')){run(()=>rcon(event.target.elements.command.value));return;}run(async()=>{if(!event.target.reportValidity())return;const p=values();if(!p.rotation.length)throw Error('Sélectionne au moins une carte.');if(p.bots>p.players-1)throw Error('Réserve une place pour un humain : bots ≤ places − 1.');await api('save',{id:selected,profile:p});try{await api('update-author',{id:selected,author:p.author||'',authorColor:p.authorColor||'#95eb35'});await window.ServersView.refreshCommunity();}catch{}await refreshList();renderForm(current());updateAddress();message('Profil enregistré. Tu peux démarrer le serveur.');});});
        overlay.addEventListener('input',event=>{if(event.target.hasAttribute('data-map-search'))renderMaps();if(['players','bots','humans'].includes(event.target.name) && event.target.value !== '')syncAllocation(event.target.name);});
        overlay.addEventListener('change',event=>{
            if(event.target.name==='mode')overlay.querySelector('.hmwh-mix-modes').hidden=event.target.value!=='mix';
            if(event.target.hasAttribute('data-map-family')){renderMaps();return;}
            if(event.target.dataset.mapChoice){const a=rotation(),m=event.target.dataset.mapChoice;setRotation(event.target.checked?[...a,m]:a.filter(v=>v!==m));return;}
            if(['players','bots','humans'].includes(event.target.name))syncAllocation(event.target.name);
            const f=overlay.querySelector('.hmwh-form');if(!f)return;
            if(event.target.name==='preset'){
                const v=event.target.value;f.elements.access.value=v==='public'?'public':'private';f.elements.players.value=v==='duel'?2:12;f.elements.bots.value=v==='training'?9:0;f.elements.mode.value=v==='duel'?'dm':'war';f.elements.rotation.value=v==='duel'?'mp_rust':'mp_rust\nmp_terminal';f.elements.scoreLimit.value=v==='duel'?20:75;f.elements.password.value=v==='public'?'':('amis-'+Math.random().toString(36).slice(2,8));
            }
            if(event.target.name==='preset'){syncAllocation();renderMaps();}
            updateAddress();
        });
        try{await refreshList();selected=profiles.find(p=>p.id===profileId)?.id||profiles[0]?.id||'srv_'+Date.now().toString(36);renderForm(current());updateAddress();await poll();timer=setInterval(poll,2500);}catch(e){message(e.message,true);}
    }

    const mapNames={convoy:'Ambush',backlot:'Backlot',bloc:'Bloc',bog:'Bog',bog_summer:'Beach Bog',broadcast:'Broadcast',carentan:'Chinatown',cargoship:'Wet Work',citystreets:'District',countdown:'Countdown',crash:'Crash',crash_snow:'Winter Crash',creek:'Creek',crossfire:'Crossfire',farm:'Downpour',farm_spring:'Daybreak',killhouse:'Killhouse',overgrown:'Overgrown',pipeline:'Pipeline',shipment:'Shipment',showdown:'Showdown',strike:'Strike',vacant:'Vacant',abandon:'Carnival',afghan:'Afghan',alpha:'Lockdown',boneyard:'Scrapyard',bootleg:'Bootleg',bravo:'Mission',brecourt:'Wasteland',checkpoint:'Karachi',compact:'Salvage',complex:'Bailout',courtyard_ss:'Erosion',derail:'Derail',dome:'Dome',estate:'Estate',favela:'Favela',fuel2:'Fuel',hardhat:'Hardhat',highrise:'Highrise',invasion:'Invasion',lambeth:'Fallen',mogadishu:'Bakaara',nightshift:'Skidrow',paris:'Resistance',plaza2:'Arkaden',quarry:'Quarry',rundown:'Rundown',rust:'Rust',seatown:'Seatown',storm:'Storm',subbase:'Sub Base',terminal:'Terminal',trailerpark:'Trailer Park',underground:'Underground',underpass:'Underpass'};
    const mwrMaps=new Set('convoy backlot bloc bog bog_summer broadcast carentan cargoship citystreets countdown crash crash_snow creek crossfire farm farm_spring killhouse overgrown pipeline shipment showdown strike vacant'.split(' ')),mw3Maps=new Set('alpha bootleg bravo courtyard_ss dome hardhat lambeth mogadishu paris plaza2 seatown underground'.split(' '));
    const mapFamily=m=>{const k=m.replace(/^mp_/,'');return mwrMaps.has(k)?'MWR':mw3Maps.has(k)?'MW3':mapNames[k]?'MW2':'custom';};
    const mapLabel=m=>mapNames[m.replace(/^mp_/,'')]||m;
    function rotation(){return overlay.querySelector('[name=rotation]').value.split(/\s+/).filter(Boolean);}
    function setRotation(a){overlay.querySelector('[name=rotation]').value=[...new Set(a)].join(' ');renderMaps();}
    const illustratedMaps = new Set(["mp_abandon","mp_afghan","mp_alpha","mp_backlot","mp_bloc","mp_bog","mp_bog_summer","mp_boneyard","mp_bootleg","mp_bravo","mp_brecourt","mp_broadcast","mp_carentan","mp_cargoship","mp_checkpoint","mp_citystreets","mp_compact","mp_complex","mp_convoy","mp_countdown","mp_courtyard_ss","mp_crash","mp_crash_snow","mp_creek","mp_crossfire","mp_derail","mp_dome","mp_estate","mp_farm","mp_farm_spring","mp_favela","mp_fuel2","mp_hardhat","mp_highrise","mp_invasion","mp_killhouse","mp_lambeth","mp_mogadishu","mp_nightshift","mp_overgrown","mp_paris","mp_pipeline","mp_plaza2","mp_quarry","mp_rundown","mp_rust","mp_seatown","mp_shipment","mp_showdown","mp_storm","mp_strike","mp_subbase","mp_terminal","mp_trailerpark","mp_underground","mp_underpass","mp_vacant"]);
    function mapArt(m){return illustratedMaps.has(m)?'<span class="hmwh-map-art"><img src="./assets/img/hmw-maps/'+esc(m)+'.jpg" alt="" loading="lazy" decoding="async"></span>':'<span class="hmwh-map-art" aria-hidden="true">▦</span>';}
    function renderMaps(){const host=overlay.querySelector('.hmwh-map-catalog');if(!host)return;const a=rotation(),q=overlay.querySelector('[data-map-search]').value.toLowerCase();
        const family=overlay.querySelector('[data-map-family]').value;host.innerHTML=maps.filter(m=>(!family||mapFamily(m)===family)&&(mapLabel(m)+' '+m).toLowerCase().includes(q)).map(m=>'<label class="hmwh-map-card '+(a.includes(m)?'selected':'')+'">'+mapArt(m)+'<span class="hmwh-map-title"><strong>'+esc(mapLabel(m))+'</strong><small>'+esc(mapFamily(m))+' · '+esc(m)+'</small></span><input type="checkbox" data-map-choice="'+esc(m)+'" '+(a.includes(m)?'checked':'')+'></label>').join('');
        overlay.querySelector('.hmwh-map-count').textContent=a.length+' carte(s)';overlay.querySelector('.hmwh-map-rotation').innerHTML=a.map((m,i)=>'<div class="hmwh-map-chip"><span class="hmwh-map-index">'+(i+1)+'</span><strong>'+esc(mapLabel(m))+'</strong><button type="button" data-rotation="-1" data-index="'+i+'" aria-label="Monter '+esc(mapLabel(m))+'" '+(i===0?'disabled':'')+'>↑</button><button type="button" data-rotation="1" data-index="'+i+'" aria-label="Descendre '+esc(mapLabel(m))+'" '+(i===a.length-1?'disabled':'')+'>↓</button><button type="button" data-remove-map="'+esc(m)+'" aria-label="Retirer '+esc(mapLabel(m))+'">×</button></div>').join('')||'<p class="hmwh-muted">Sélectionne au moins une carte avant d’enregistrer.</p>';
    }
    function colorLog(log){return log.split(/\r?\n/).map(line=>{const type=/error|fatal|failed|exception|script runtime/i.test(line)?'error':/warn|protected|missing|not found|could not|bad request|not seem to be registered|read only/i.test(line)?'warn':/WARLINK_.*READY|success|server started|complete|listening/i.test(line)?'success':/map|fastfile|zone/i.test(line)?'map':/model|material|texture|image/i.test(line)?'asset':'';return '<span class="hmwh-log-'+type+'">'+esc(line)+'</span>';}).join('\n');}
    function networkHelp(error=''){message(error,true);window.WarlinkNetworkGuide.open(selected,error);}

    function updateAddress(){const form=overlay?.querySelector('.hmwh-form');if(form)overlay.querySelector('.hmwh-address').textContent=`connect 127.0.0.1:${(current()?.port||form.elements.port.value)}`;overlay.querySelector('.hmwh-share-address').textContent='Adresse non publiée';overlay.querySelector('[data-copy-connect="share"]').disabled=true;}
    document.addEventListener('click',e=>{if(e.target.closest('[data-hmw-host]'))open();});
    window.HMWHost={open};
})();
